{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 동물보호 조례상 동물복지위원회 위촉직 위원의 70%를 한 성별로 구성할 때, 전문인력 부족 사정만 있고 양성평등실무위원회 의결이 없으면 성별 비율 예외를 적용할 수 있는지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "적용할 수 없다. 서울특별시 동물보호 조례 제5조제2항 본문은 위촉직 위원 구성 시 특정 성별이 위촉직 위원 수의 10분의 6을 초과하지 않도록 하여야 한다고 정하고 있으므로, 70%를 한 성별로 구성하는 것은 이 기준에 맞지 않는다. 같은 항 단서는 해당 분야 특정 성별의 전문인력 부족 등 부득이한 사유가 있다고 인정되어 양성평등실무위원회의 의결을 거친 경우에만 예외를 인정하므로, 전문인력 부족 사정만 있고 양성평등실무위원회의 의결이 없으면 예외를 적용할 수 없다.",
          "b_ids": "동물보호:제5조제2항, 동물보호:제5조제2항단서"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
